// Builds the weekly report from three CSPM responses. Every figure below is
// read from them; nothing is estimated. Where the API has no data (no
// completed scan in the period) the report says so instead of showing a number.
const summary = $('Get CSPM Dashboard Summary').first().json;
const compliance = $('Get Compliance Summary').first().json;
const failed = $('Get Failed Findings').first().json;

const SEVERITY_ORDER = ['critical', 'high', 'medium', 'low', 'info'];
const rank = (severity) => {
  const index = SEVERITY_ORDER.indexOf(severity);
  return index === -1 ? SEVERITY_ORDER.length : index;
};
const escapeHtml = (value) =>
  String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
const percent = (value) => (value === null || value === undefined ? null : `${Number(value).toFixed(1)}%`);

// Failed checks grouped by check: the checks that fail on most resources,
// most severe first. Severity is the one the check declares; a check that is
// no longer in the catalogue has none and sorts last.
const byCheck = new Map();
for (const finding of failed.findings || []) {
  const entry = byCheck.get(finding.check_id) || {
    check_id: finding.check_id,
    title: finding.title,
    severity: finding.severity || null,
    remediation: finding.remediation || null,
    resources: new Set(),
  };
  entry.resources.add(finding.resource_id);
  byCheck.set(finding.check_id, entry);
}
const topRisks = [...byCheck.values()]
  .sort((a, b) => rank(a.severity) - rank(b.severity) || b.resources.size - a.resources.size)
  .slice(0, 5)
  .map((entry) => ({
    check_id: entry.check_id,
    title: entry.title,
    severity: entry.severity,
    resources_affected: entry.resources.size,
    remediation: entry.remediation,
  }));

const assessed = summary.accounts_assessed > 0;
const findingsShown = (failed.findings || []).length;
const report = {
  report_date: new Date().toISOString().split('T')[0],
  period_days: summary.summary_period_days,
  assessed,
  total_scans: summary.total_scans,
  last_scan_at: summary.last_scan_at,
  accounts_assessed: summary.accounts_assessed,
  compliance_score: summary.compliance_score,
  findings: {
    total: summary.total_findings,
    critical: summary.critical_findings,
    high: summary.high_findings,
    medium: summary.medium_findings,
    low: summary.low_findings,
    info: summary.info_findings,
    unknown_severity: summary.unknown_severity_findings,
  },
  resources: {
    total: compliance.total_resources,
    compliant: compliance.compliant_resources,
    non_compliant: compliance.non_compliant_resources,
  },
  frameworks: (compliance.frameworks || []).map((framework) => ({
    name: framework.name,
    compliance_percentage: framework.compliance_percentage,
    passed_checks: framework.passed_checks,
    total_checks: framework.total_checks,
  })),
  top_risks: topRisks,
  // The findings endpoint pages at 1000; when there are more failed checks the
  // grouping covers the first page only, and the report says so.
  failed_findings_considered: findingsShown,
  failed_findings_total: failed.total_count,
};

const lines = [];
lines.push(`Cloud security report, ${report.report_date} (last ${report.period_days} days)`);
if (!assessed) {
  lines.push('No completed CSPM scan in the period: there are no figures to report.');
} else {
  lines.push(`Accounts assessed: ${report.accounts_assessed}`);
  lines.push(`Compliance score: ${percent(report.compliance_score) ?? 'not assessed'}`);
  lines.push(
    `Failed checks: ${report.findings.total} (critical ${report.findings.critical}, high ${report.findings.high}, ` +
      `medium ${report.findings.medium}, low ${report.findings.low})`,
  );
}
const text = lines.join('\n');

const rows = [
  ['Accounts assessed', report.accounts_assessed],
  ['Scans (retained)', report.total_scans],
  ['Compliance score', percent(report.compliance_score) ?? 'Not assessed'],
  ['Resources with a failed check', `${report.resources.non_compliant} of ${report.resources.total}`],
  ['Failed checks', report.findings.total],
  ['Critical', report.findings.critical],
  ['High', report.findings.high],
  ['Medium', report.findings.medium],
  ['Low', report.findings.low],
  ['Informational', report.findings.info],
];
if (report.findings.unknown_severity > 0) {
  rows.push(['Severity unknown (check no longer in the catalogue)', report.findings.unknown_severity]);
}

let html = `<h2>Cloud security report, ${escapeHtml(report.report_date)}</h2>`;
html += `<p>Figures from the newest completed CSPM scan of each account in the last ${escapeHtml(report.period_days)} days.</p>`;
if (!assessed) {
  html += '<p><strong>No completed CSPM scan in the period: there are no figures to report.</strong></p>';
} else {
  html += '<table border="1" cellpadding="4" style="border-collapse: collapse;">';
  for (const [label, value] of rows) {
    html += `<tr><td>${escapeHtml(label)}</td><td>${escapeHtml(value)}</td></tr>`;
  }
  html += '</table>';

  if (report.frameworks.length) {
    html += '<h3>Compliance by framework</h3><ul>';
    for (const framework of report.frameworks) {
      html +=
        `<li>${escapeHtml(framework.name)}: ${escapeHtml(percent(framework.compliance_percentage))} ` +
        `(${escapeHtml(framework.passed_checks)} of ${escapeHtml(framework.total_checks)} checks passed)</li>`;
    }
    html += '</ul>';
  }

  html += '<h3>Failing checks</h3>';
  if (!report.top_risks.length) {
    html += '<p>No check failed.</p>';
  } else {
    html += '<ol>';
    for (const risk of report.top_risks) {
      html +=
        `<li><strong>${escapeHtml(risk.title)}</strong> (${escapeHtml(risk.severity || 'severity unknown')}, ` +
        `${escapeHtml(risk.resources_affected)} resource(s))`;
      if (risk.remediation) {
        html += `<br>Remediation: ${escapeHtml(risk.remediation)}`;
      }
      html += '</li>';
    }
    html += '</ol>';
    if (report.failed_findings_total > report.failed_findings_considered) {
      html +=
        `<p>Grouped from the first ${escapeHtml(report.failed_findings_considered)} of ` +
        `${escapeHtml(report.failed_findings_total)} failed checks.</p>`;
    }
  }
}

return [{ json: { ...report, text, html } }];
